import './App.css';

function App() {
  return (
    <main className="app-shell">
      <section className="intro" aria-labelledby="page-title">
        <p className="eyebrow">Hack-n-Hub</p>
        <h1 id="page-title">Construa o proximo grande projeto.</h1>
        <p className="description">
          A base do frontend esta pronta. Comece a transformar a sua ideia em uma experiencia real.
        </p>
        <button type="button">Comecar projeto</button>
      </section>
    </main>
  );
}

export default App;
